import json

def main(retrieve_items: str) -> dict:
    
    json_items = json.loads(retrieve_items)
    all_query_items = json.loads(json_items['results'])
    for idx, item in enumerate(all_query_items):
        item['id'] = idx + 1
    title_entity_dict = {k['id']:k for k in all_query_items}
    for_filter_data = [{'id':i['id'],'title':i['title'],'content':i['content'],'source':i['source']} for i in all_query_items]

    return {
        "title_entity_dict": title_entity_dict,
        "for_filter_data": json.dumps(for_filter_data,ensure_ascii=False)
    }


filter_data = '''
[1, 3, 4, 7, 8, 18, 19, 23]
'''
import json
def main2(filter_data: str, title_entity_dict: dict) -> dict:
    filter_data = filter_data.strip()
    start_idx = filter_data.find('[')
    end_idx = filter_data.rfind(']') + 1
    json_items = json.loads(filter_data[start_idx:end_idx])
    
    reduce_data = []
    for_llm_data = []
    reidx_id = 1
    for item in json_items:
        raw_entity = title_entity_dict[str(item)]
        for_llm_data.append({'id':reidx_id,'title':raw_entity['title'],'content':raw_entity['content']})
        reduce_data.append({**raw_entity,'id':reidx_id})
        reidx_id += 1

    ref_str = '\n'.join([f'[{i["title"]}]({i["url"]})' for i in reduce_data])
    ref_with_idx = '\n'.join([f'{i["id"]}.[{i["title"]}]({i["url"]})' for i in reduce_data])
    
    return {
        "reduce_data": json.dumps(reduce_data,ensure_ascii=False),
        "ref_str": ref_str,
        'ref_with_idx': ref_with_idx
    }

main2(filter_data,main(demo_str)['title_entity_dict'])